{
  "lecture": [
    {
      "etiquette": "F36",
      "R1": {
        "valeur": 1,
        "passage": "couverture égale à une composante près sur les 24 mondes, coût par génération réduit d'au moins 40 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "ce que l'oracle dit des composantes couvertes et des lois fausses ou copiées promues, et ce que les relais relèvent en dollars et en jetons"
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucun autre réglage n'est touché, et aucun agent ne voit de verdict."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "La valeur est annoncée fixe pendant la course, mais un retour à la valeur actuelle dépend de l'absence de cartes valides, sans préciser quand ni comment appliquer ce retour."
      },
      "R6": {
        "valeur": 1,
        "passage": "de l'ordre de 115 USD sur l'ensemble ; un premier passage de 5 mondes, vers 25 USD, dit si le signe tient"
      },
      "R7": {
        "valeur": 0,
        "motif": "La fiche ne relie pas la réduction des exemples à une baisse de puissance du juge et n'explique pas pourquoi cette baisse préserverait la couverture tout en réduisant le coût de 40 %."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F37",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle dans les retenues en fin de course augmente d'au moins 20 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes et dans les retenues, nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 1,
        "passage": "en respectant strictement l'interdiction de tout score de juge, de toute prime de nouveauté, de tout quota de formes et de tout masquage de l'archive."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "Insérer cette table factuelle en annexe de la liste intégrale des lois de l'archive dans la vue publique, sans ajouter aucune consigne prescriptive, ni quota, ni score."
      },
      "R6": {
        "valeur": 1,
        "passage": "à effectuer une seule passe d'appels aux proposeurs avec la vue augmentée de la table syntaxique (quelques dollars d'appels)"
      },
      "R7": {
        "valeur": 0,
        "motif": "La table rend les fréquences syntaxiques visibles sans expliquer pourquoi elles orienteraient vers les couples absents plutôt que vers les couples fréquents, possibilité contraire explicitement reconnue."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F38",
      "R1": {
        "valeur": 1,
        "passage": "à budget d'épisodes du test de mort égal, au moins 20 % de composantes plantées couvertes en plus par génération que l'ordre d'arrivée actuel"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes par génération et lois fausses retenues, lues par l'oracle après la course ; dollars des juges à modèle relevés par les relais"
      },
      "R3": {
        "valeur": 0,
        "motif": "Les préférences d'un juge à modèle déterminent les cotes qui sélectionnent les cartes accédant au test de mort, sans justification explicite rouvrant cette interdiction."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche étiquetée levier:juge ne nomme aucune garantie statistique conservée ni le nul contre lequel elle resterait démontrable."
      },
      "R5": {
        "valeur": 1,
        "passage": "les cotes se mettent à jour avec un facteur K = 32 ; huit tours. Le test de mort prend ensuite les cartes par cote décroissante jusqu'à épuisement de ses épisodes."
      },
      "R6": {
        "valeur": 1,
        "passage": "de l'ordre de 3 USD de juges à modèle par génération, soit environ 120 USD pour quarante mondes, le test de mort et l'ordre tiré au hasard se rejouant sur processeur"
      },
      "R7": {
        "valeur": 0,
        "motif": "Qualifier les cartes préférées de plus prometteuses ne fournit aucun lien entre les cotes Elo et les composantes vraies additionnelles, et la préférence peut favoriser des lois fausses."
      },
      "N": {
        "valeur": "C1",
        "passage_fiche": "Les mieux classées se départagent en débats à plusieurs tours, les autres en une comparaison ; les paires sont tirées entre cartes proches, et le test de mort suit l'ordre des cotes.",
        "passage_catalogue": "Un agent de classement tient un **tournoi à cotes Elo** (1 200 au départ) entre hypothèses, par **comparaisons appariées**"
      }
    },
    {
      "etiquette": "F39",
      "R1": {
        "valeur": 1,
        "passage": "couverture des composantes plantées inchangée (écart nul à une composante près sur l'ensemble des trente mondes) pour au moins 35 % de tirages frais en moins par génération"
      },
      "R2": {
        "valeur": 0,
        "motif": "La prédiction exige aussi qu'au moins la moitié des cartes déclarées sans apport le soient par le juge actuel, faisant dépendre un critère de réussite du verdict du juge."
      },
      "R3": {
        "valeur": 1,
        "passage": "la valeur e de la carte est calculée sur ces seuls tirages, contre le même nul."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La fiche ne définit ni le choix de la meilleure loi de l'archive, ni la construction de la séquence de confiance, ni sa règle de décision."
      },
      "R6": {
        "valeur": 1,
        "passage": "rejouable sur processeur avec des mondes plantés simulés : environ 8 heures de calcul pour trente graines et deux bras, aucun appel de proposeur ni de juge à modèle"
      },
      "R7": {
        "valeur": 0,
        "motif": "Échantillonner seulement les désaccords explique une économie, mais pas la couverture inchangée puisque le seuil peut éliminer une composante rare, conformément au risque de dilution décrit dans les faits."
      },
      "N": {
        "valeur": "C9",
        "passage_fiche": "le juge ne tire des issues fraîches que sur des instances de désaccord échantillonnées, et décide par une séquence de confiance valide à tout instant.",
        "passage_catalogue": "un palier audité **n'étiquette que des désaccords échantillonnés**, par une **séquence de confiance valide à tout instant**."
      }
    }
  ]
}
